// 计算两点间距离
export function calculateDistance(x1, y1, x2, y2) {
    return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

// 计算绳子总长度
export function calculateRopeLength({
    boatX,
    boatY,
    pulleyX,
    pulleyY,
    anchorX
}) {
    const boatToPulley = calculateDistance(
        boatX, boatY, pulleyX, pulleyY
    );
    const pulleyToAnchor = Math.abs(pulleyX - anchorX);
    return boatToPulley + pulleyToAnchor;
}

// 已知支点位置，反算船的位置
export function calculateBoatX({
    ropeTotalLength,
    pulleyX,
    pulleyY,
    boatY,
    anchorX
}) {
    const d = Math.abs(pulleyX - anchorX);
    const remaining = ropeTotalLength - d;
    const H = pulleyY - boatY;

    if (remaining <= H) {
        return pulleyX + 0.01; // 防止数学异常
    }

    return pulleyX + Math.sqrt(remaining ** 2 - H ** 2);
}

export function computeRopeAngle({
    boatAttachX,   // 船上绳子连接点 x（米）
    boatAttachY,   // 船上绳子连接点 y（米）
    pulleyCenterX, // 滑轮中心 x（米）
    pulleyCenterY, // 滑轮中心 y（米）
}) {
    const dx = boatAttachX - pulleyCenterX;
    const dy = pulleyCenterY - boatAttachY;

    return Math.atan2(dy, dx);
}
