/* eslint-disable no-unused-vars */
function drawArrow(ctx, x, y, vx, vy, color) {
    const scale = 20; // 速度 → 像素缩放（只影响显示）
    const endX = x + vx * scale;
    const endY = y + vy * scale;

    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 2;

    // 主线
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // 箭头
    const angle = Math.atan2(endY - y, endX - x);
    const headLen = 8;

    ctx.beginPath();
    ctx.moveTo(endX, endY);
    ctx.lineTo(
        endX - headLen * Math.cos(angle - Math.PI / 6),
        endY - headLen * Math.sin(angle - Math.PI / 6)
    );
    ctx.lineTo(
        endX - headLen * Math.cos(angle + Math.PI / 6),
        endY - headLen * Math.sin(angle + Math.PI / 6)
    );
    ctx.closePath();
    ctx.fill();
}

// 画整个场景（目前只画静态几何）
export function drawScene(ctx, state, config) {
    console.log("drawScene 已执行（测试）");

    // ===== 1. 解构参数（关键一步）=====
    const {
        boatX,
        boatY,
        anchorX,
        ropeAngle,
        boatHorizontalSpeed,
        ropeTotalLength,
        horizontalDistance,
        pullingStatus,
        ropeSpeed,
    } = state;

    const {
        canvasWidth,
        canvasHeight,
        scale,
        pulleyX,
        pulleyY,
        boatTopWidth,
        pulleyRadius,
        bracketLength,
    } = config;

    // ===== 2. 背景 =====
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);

    // ===== 3. 水面 =====
    const waterY = canvasHeight - boatY * scale;

    ctx.strokeStyle = "#000";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, waterY);
    ctx.lineTo(canvasWidth, waterY);
    ctx.stroke();

    // === 4. 墙（滑轮正下方的竖直线）===
    const pulleyScreenX = pulleyX * scale;
    const pulleyScreenY = canvasHeight - pulleyY * scale;
    const cornerX = pulleyScreenX;
    const cornerY = canvasHeight - pulleyY * scale;

    ctx.beginPath();
    ctx.moveTo(cornerX, cornerY);
    ctx.lineTo(cornerX, canvasHeight);
    ctx.strokeStyle = "red";
    ctx.lineWidth = 4;
    ctx.stroke();


    // === 5. 地面（红色水平线）===
    ctx.beginPath();
    ctx.moveTo(cornerX, cornerY);
    ctx.lineTo(0, cornerY);
    ctx.strokeStyle = "red";
    ctx.lineWidth = 4;
    ctx.stroke();

    // === 6. 支架 ===
    const bracketAngle = Math.PI / 4;      // 45°
    const pulleyCenterX = cornerX + bracketLength * Math.cos(bracketAngle);
    const pulleyCenterY = cornerY - bracketLength * Math.sin(bracketAngle);

    ctx.beginPath();
    ctx.moveTo(cornerX, cornerY);
    ctx.lineTo(pulleyCenterX, pulleyCenterY);
    ctx.strokeStyle = "red";
    ctx.lineWidth = 3;
    ctx.stroke();

    // === 7. 滑轮（画成一个小圆）===
    ctx.beginPath();
    ctx.arc(
        pulleyCenterX,
        pulleyCenterY,
        pulleyRadius,
        0,
        Math.PI * 2
    );
    ctx.fillStyle = "red";
    ctx.fill();
    ctx.strokeStyle = "red";
    ctx.lineWidth = 3;
    ctx.stroke();

    // ===== 8. 小船：倒等腰梯形（上底长，下底短）=====
    ctx.strokeStyle = "#000";
    ctx.lineWidth = 2;

    const boatBottomWidth = 40;
    const boatHeight = 30;

    // 船底中心（世界坐标 → 像素）
    const boatCenterX = boatX * scale;
    const boatCenterY = waterY;

    const topLeft = {
        x: boatCenterX - boatTopWidth / 2,
        y: boatCenterY - boatHeight,
    };
    const topRight = {
        x: boatCenterX + boatTopWidth / 2,
        y: boatCenterY - boatHeight,
    };
    const bottomRight = {
        x: boatCenterX + boatBottomWidth / 2,
        y: boatCenterY,
    };
    const bottomLeft = {
        x: boatCenterX - boatBottomWidth / 2,
        y: boatCenterY,
    };

    ctx.beginPath();
    ctx.moveTo(topLeft.x, topLeft.y);
    ctx.lineTo(topRight.x, topRight.y);
    ctx.lineTo(bottomRight.x, bottomRight.y);
    ctx.lineTo(bottomLeft.x, bottomLeft.y);
    ctx.closePath();
    ctx.stroke();

    // ===== 9. 绳子（必须经过滑轮）=====
    const px = topLeft.x;
    const py = topLeft.y;
    const ox = pulleyCenterX;
    const oy = pulleyCenterY;
    const R = pulleyRadius;
    const dx = px - ox;
    const dy = py - oy;
    const distPO = Math.hypot(dx, dy);
    const anglePO = Math.atan2(dy, dx);
    const alpha = Math.acos(R / distPO);
    const theta = anglePO - alpha;
    const tx = ox + R * Math.cos(theta);
    const ty = oy + R * Math.sin(theta);
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(tx, ty);
    ctx.stroke();

    const ropeEndX = anchorX * scale;
    const ropeEndY = pulleyCenterY - pulleyRadius;
    ctx.beginPath();
    ctx.moveTo(
        pulleyCenterX,
        pulleyCenterY - pulleyRadius
    );
    ctx.lineTo(ropeEndX, ropeEndY);
    ctx.stroke();

    const angleTop = -Math.PI / 2; // 圆的最高点（水平绳）
    const angleBoat = Math.atan2(ty - oy, tx - ox);
    ctx.beginPath();
    ctx.arc(
        ox,
        oy,
        R,
        angleTop,
        angleBoat,
        false   // 顺时针，画劣弧
    );
    ctx.strokeStyle = "#000";
    ctx.stroke();

    // ===== 10. 箭头（从连接点起）=====

    //沿绳方向
    const ropeDirX = tx - px;
    const ropeDirY = ty - py;
    const ropeLen = Math.hypot(ropeDirX, ropeDirY);

    const ux = ropeDirX / ropeLen;
    const uy = ropeDirY / ropeLen;

    drawArrow(
        ctx,
        px,
        py,
        ux * ropeSpeed.value,
        uy * ropeSpeed.value,
        "red"
    );

    //垂直绳方向
    const vPerp = ropeSpeed.value * Math.tan(
        ropeAngle.value * Math.PI / 180
    );

    drawArrow(
        ctx,
        px,
        py,
        uy * vPerp,
        -ux * vPerp,
        "blue"
    );

    //合速度
    drawArrow(
        ctx,
        px,
        py,
        -boatHorizontalSpeed.value,
        0,
        "green"
    );
}