<template>
    <div id="app">
        <canvas ref="canvasRef" width="1200" height="600"></canvas>
        <div class="controls">
            <button @mousedown="startPulling" @mouseup="stopPulling" @mouseleave="stopPulling">开始匀速拉绳</button>
            <button @click="resetScene">重置场景</button>
            <div class="info">绳子总长度: {{ ropeTotalLength.toFixed(1) }}m</div>
            <div class="info">沿绳速度: {{ ropeSpeed.toFixed(2) }} m/s</div>
            <div class="info">船的水平速度: {{ boatHorizontalSpeed.toFixed(2) }} m/s</div>
            <div class="info">绳子与水平夹角: {{ ropeAngle.toFixed(1) }}°</div>
            <div class="info">水平距离: {{ horizontalDistance.toFixed(1) }}m</div>
            <div class="info">当前状态: {{ pullingStatus }}</div>
            <div class="info">计算次数: {{ frameCount }}</div>
        </div>
        <div class="key-hint">
            <p>按住"开始匀速拉绳"按钮，观察船的速度变化</p>
            <p>理论: v_船 = v_绳 / cosθ</p>
            <p>当θ增大时，船的水平速度增大</p>
        </div>
        <div class="velocity-diagram">
            <div class="diagram-title">速度分解示意图</div>
            <div class="diagram-content">
                <div class="velocity-vector rope-velocity">
                    <div class="arrow"></div>
                    <div class="label">v_绳 = {{ ropeSpeed.toFixed(2) }} m/s (恒定)</div>
                </div>
                <div class="velocity-vector horizontal-velocity">
                    <div class="arrow"></div>
                    <div class="label">v_船 = {{ boatHorizontalSpeed.toFixed(2) }} m/s</div>
                </div>
                <div class="angle-label">θ = {{ ropeAngle.toFixed(1) }}°</div>
                <div class="formula" v-if="ropeAngle > 0.1">
                    v_船 = v_绳 / cos({{ ropeAngle.toFixed(1) }}°) = {{ ropeSpeed.toFixed(2) }} / {{ Math.cos(ropeAngle * Math.PI / 180).toFixed(3) }} = {{ calculatedBoatSpeed.toFixed(2) }} m/s
                </div>
            </div>
        </div>
    </div>
</template>

<script>
/* eslint-disable no-unused-vars */
import { onMounted, onUnmounted, ref, computed } from "vue";
import {
    calculateDistance,
    calculateRopeLength,
    calculateBoatX
} from "./physics/ropeBoatModel";
import { drawScene } from "./canvas/drawScene";
import { computeRopeAngle } from "./physics/ropeBoatModel";

export default {
    name: "App",
    setup() {
        const canvasRef = ref(null);
        let ctx = null;
        let animationFrameId = null;
        let lastTime = 0;
        
        // 物理参数
        const ropeTotalLength = ref(30); // 米，绳子总长度（固定）
        const ropeSpeed = ref(2.0); // 米/秒，沿绳方向的恒定速度
        const boatHorizontalSpeed = ref(0); // 船的水平速度
        const ropeAngle = ref(0); // 绳子与水平方向的夹角（度）
        const horizontalDistance = ref(0); // 船与滑轮的水平距离
        const pullingStatus = ref("静止");
        const frameCount = ref(0);
        
        // 场景参数（使用米作为单位，最后转换为像素）
        const pulleyX = 10; // 米，滑轮X坐标
        const pulleyY = 5;  // 米，滑轮Y坐标
        const boatY = 0;    // 米，船的固定Y坐标（水面）
        
        // 状态变量
        let anchorX = pulleyX - 10; // 米，支点X坐标
        let boatX = pulleyX + 20;   // 米，船X坐标（初始在滑轮右侧）
        let isPulling = false;
        let startTime = 0;
        let elapsedTime = 0;

        // 几何参数
        const bracketLength = 1.5;      // 支架长度（米）
        const pulleyRadius = 0.5;       // 滑轮半径（米）
        const bracketAngle = Math.PI / 4; // 45°

        // 滑轮圆心（由墙角 + 支架确定）
        const pulleyCenterX = pulleyX + bracketLength * Math.cos(bracketAngle);
        const pulleyCenterY = pulleyY + bracketLength * Math.sin(bracketAngle);
        
        // 缩放因子：1米 = 多少像素
        const scale = 30; // 1米 = 30像素
        const canvasWidth = 1200;
        const canvasHeight = 600;

        // ===== 几何常量（物理 + 绘图共用）=====
        const boatTopWidth = 80;     // 像素

        onMounted(() => {
            initScene();
            startAnimation();
        });

        const calculatedBoatSpeed = computed(() => {
            if (ropeAngle.value === 0) return ropeSpeed.value;
            return ropeSpeed.value / Math.cos(ropeAngle.value * Math.PI / 180);
        });

        const initScene = () => {
            if (!canvasRef.value) return;
            
            ctx = canvasRef.value.getContext('2d');
            
            // 初始化位置
            anchorX = pulleyX - 10;
            boatX = pulleyX + 20;
            isPulling = false;
            startTime = 0;
            elapsedTime = 0;
            ropeAngle.value = 0;
            boatHorizontalSpeed.value = 0;
            horizontalDistance.value = boatX - pulleyCenterX - pulleyRadius - (boatTopWidth / 2) / scale;
            frameCount.value = 0;
            pullingStatus.value = "静止";
            
            // 计算初始绳子总长度（用于验证）
            const initialRopeLength = calculateRopeLength({
                boatX,
                boatY,
                pulleyX,
                pulleyY,
                anchorX
            });
            ropeTotalLength.value = initialRopeLength;
            
            // 绘制初始场景
            drawScene(ctx, {
                boatX,
                boatY,
                anchorX,
                ropeAngle,
                boatHorizontalSpeed,
                ropeTotalLength,
                horizontalDistance,
                pullingStatus,
                ropeSpeed,
            }, {
                canvasWidth,
                canvasHeight,
                scale,
                pulleyX,
                pulleyY,
                boatTopWidth,
                pulleyRadius: pulleyRadius * scale,
                bracketLength:bracketLength * scale,
            });

        };

        const startAnimation = () => {
            const animate = (currentTime) => {
                if (!lastTime) lastTime = currentTime;
                const deltaTime = (currentTime - lastTime) / 1000; // 转换为秒
                lastTime = currentTime;
                
                // 更新场景
                updateScene(deltaTime);
                
                // 绘制场景
                drawScene(ctx, {
                    boatX,
                    boatY,
                    anchorX,
                    ropeAngle,
                    boatHorizontalSpeed,
                    ropeTotalLength,
                    horizontalDistance,
                    pullingStatus,
                    ropeSpeed,
                }, {
                    canvasWidth,
                    canvasHeight,
                    scale,
                    pulleyX,
                    pulleyY,
                    boatTopWidth,
                    pulleyRadius: pulleyRadius * scale,
                    bracketLength:bracketLength * scale,
                });

                
                // 继续动画循环
                animationFrameId = requestAnimationFrame(animate);
            };
            
            animationFrameId = requestAnimationFrame(animate);
        };

        const updateScene = (deltaTime) => {
            if (!isPulling) return;

            // 1. 试探性移动支点（水平拉绳）
            const proposedAnchorX = anchorX - ropeSpeed.value * deltaTime;

            // 2. 用“试探支点”反算船位置
            const proposedBoatX = calculateBoatX({
                ropeTotalLength: ropeTotalLength.value,
                pulleyX: pulleyCenterX,
                pulleyY: pulleyCenterY,
                boatY,
                anchorX: proposedAnchorX,
            });

            // 3. 判断：滑轮-船绳是否已竖直
            const dx = proposedBoatX - (boatTopWidth / 2) / scale - pulleyCenterX - pulleyRadius;
            const dy = pulleyCenterY - boatY;
            const theta = Math.atan2(dy, dx); // 弧度
            const epsilonAngle = 1e-3;

            if (Math.abs(Math.cos(theta)) < epsilonAngle) {
                pullingStatus.value = "绳已竖直，无法继续拉动";
                boatHorizontalSpeed.value = 0;
                return;
            }

            // 4. 真正更新
            anchorX = proposedAnchorX;
            const cosTheta = Math.cos(theta);
            if (Math.abs(cosTheta) < 1e-3) {
                boatHorizontalSpeed.value = Infinity;
            } else {
                boatHorizontalSpeed.value = ropeSpeed.value / cosTheta;
            }
            boatX = proposedBoatX;

            // 5. 更新几何量（用于显示）
            ropeAngle.value = Math.atan2(dy, dx) * 180 / Math.PI;
            horizontalDistance.value = dx;
        };

        const startPulling = () => {
            if (isPulling) return;
            isPulling = true;
            startTime = performance.now();
            elapsedTime = 0;
        };

        const stopPulling = () => {
            isPulling = false;
        };

        const resetScene = () => {
            isPulling = false;
            initScene();
        };

        onUnmounted(() => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        });

        return {
            canvasRef,
            ropeTotalLength,
            ropeSpeed,
            boatHorizontalSpeed,
            ropeAngle,
            horizontalDistance,
            pullingStatus,
            frameCount,
            calculatedBoatSpeed,
            startPulling,
            stopPulling,
            resetScene,
            Math
        };
    }
};
import "./styles/app.css";
</script>